function event_scale_calc(e)

    local playerrace = e.owner:GetRace();
    local playerclass = e.owner:GetClass();
    local group = e.owner:GetGroup();
    local member;
    local matchcount = 0;

    if(group) then
        for i = 1,6,1 do
